const headers = $input.first().json.headers || {};
const h = Object.fromEntries(Object.entries(headers).map(([k, v]) => [String(k).toLowerCase(), v]));
const expected = $env.N8N_MOVFIT_PROXY_TOKEN || 'movfit_proxy_k7x9m2pQ4wR9';
const got = h['x-movfit-proxy'] || '';
if (got !== expected) {
  return [{ json: { ok: false, status: 401, error: 'Unauthorized' } }];
}
const body = $input.first().json.body || $input.first().json;
const acao = String(body.acao || (body.code ? 'token' : '')).toLowerCase();
if (!acao) {
  return [{ json: { ok: false, status: 400, error: 'acao obrigatória: registrar | token | refresh' } }];
}
return [{ json: { ok: true, acao, body } }];

const { acao, body } = $input.first().json;
const http = this.helpers.httpRequest.bind(this.helpers);

try {
  if (acao === 'registrar') {
    const endpoint = body.registration_endpoint;
    const redirectUri = body.redirect_uri;
    if (!endpoint || !redirectUri) throw new Error('registration_endpoint e redirect_uri obrigatórios');
    const data = await http({
      method: 'POST',
      url: endpoint,
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: {
        client_name: 'MovFit Gestão',
        redirect_uris: [redirectUri],
        grant_types: ['authorization_code', 'refresh_token'],
        response_types: ['code'],
        token_endpoint_auth_method: 'none',
      },
      json: true,
    });
    return [{ json: data }];
  }

  if (acao === 'token') {
    const endpoint = body.token_endpoint;
    if (!endpoint) throw new Error('token_endpoint obrigatório');
    const form = new URLSearchParams();
    form.set('grant_type', 'authorization_code');
    form.set('code', body.code);
    form.set('redirect_uri', body.redirect_uri);
    form.set('client_id', body.client_id);
    form.set('code_verifier', body.code_verifier);
    if (body.resource) form.set('resource', body.resource);
    const data = await http({
      method: 'POST',
      url: endpoint,
      headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
      body: form.toString(),
      json: true,
    });
    return [{ json: data }];
  }

  if (acao === 'refresh') {
    const endpoint = body.token_endpoint;
    if (!endpoint) throw new Error('token_endpoint obrigatório');
    const form = new URLSearchParams();
    form.set('grant_type', 'refresh_token');
    form.set('refresh_token', body.refresh_token);
    form.set('client_id', body.client_id);
    if (body.resource) form.set('resource', body.resource);
    const data = await http({
      method: 'POST',
      url: endpoint,
      headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
      body: form.toString(),
      json: true,
    });
    return [{ json: data }];
  }

  throw new Error('acao inválida');
} catch (e) {
  const msg = e.message || String(e);
  return [{ json: { error: msg } }];
}
